/**
 * The edge's package verification held to the engine's, vector by vector.
 *
 * docs/plugin-package-vectors.json (generated by the engine lane from the
 * engine's own code) is the source when it exists. Until it lands, the
 * interim file test/fixtures/package-vectors.interim.json stands in: made by
 * a generator that runs the engine's signing.rs, manifest.rs, package.rs and
 * install.rs `parse` verbatim against the same serde_json (float_roundtrip),
 * semver 1.0.28, base64 0.22 and ring as the engine builds with.
 */
import { existsSync, readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { JsonError, canonicalJson, isObject, parseJsonText } from "./json";
import { idProblem, readManifest } from "./manifest";
import { PackageRefusal, checkSignature, contentHash, signaturePayload, verifyPackage } from "./package";
import { plainPath } from "./paths";
import { comparePre, parseSemver } from "./semver";

const here = dirname(fileURLToPath(import.meta.url));
const shared = resolve(here, "../../../docs/plugin-package-vectors.json");
const interim = resolve(here, "../../test/fixtures/package-vectors.interim.json");
const source = existsSync(shared) ? shared : interim;
// eslint-disable-next-line @typescript-eslint/no-explicit-any
const vectors: any = JSON.parse(readFileSync(source, "utf8"));

const fromB64 = (s: string): Uint8Array => new Uint8Array(Buffer.from(s, "base64"));
const hashesOf = (files: Record<string, string>) => new Map(Object.entries(files));

describe(`package vectors (${source.endsWith("interim.json") ? "interim" : "shared"})`, () => {
  it("canonical JSON", () => {
    for (const v of vectors.canonical_json) {
      if (v.error) {
        expect(() => parseJsonText(v.input), v.name).toThrow(JsonError);
      } else {
        expect(canonicalJson(parseJsonText(v.input)), v.name).toBe(v.canonical);
      }
    }
  });

  it("content hashes", async () => {
    for (const v of vectors.content_hash) {
      const manifest = parseJsonText(v.manifest);
      const files = typeof v.files === "string" ? JSON.parse(v.files) : v.files;
      expect(isObject(manifest)).toBe(true);
      if (!isObject(manifest)) continue;
      expect(await contentHash(manifest, hashesOf(files)), v.name).toBe(v.hash);
    }
  });

  it("signatures", async () => {
    for (const v of vectors.signatures) {
      const manifest = parseJsonText(v.manifest);
      const files = hashesOf(v.files);
      if (isObject(manifest)) {
        const signature = manifest.get("signature");
        const key = isObject(signature) && typeof signature.get("key") === "string" ? (signature.get("key") as string) : v.key;
        if (v.payload && key) expect(signaturePayload(v.prefix, manifest, key, files), v.name).toBe(v.payload);
      }
      const checked = await checkSignature(v.prefix, manifest, files);
      expect("valid" in checked ? "valid" : checked.invalid, v.name).toBe(v.result);
    }
  });

  it("paths", () => {
    for (const v of vectors.paths) expect(plainPath(v.path), JSON.stringify(v.path)).toBe(v.ok);
  });

  it("manifests", () => {
    for (const v of vectors.manifests) {
      const raw = parseJsonText(v.manifest);
      if (!isObject(raw)) throw new Error(v.name);
      const m = readManifest(raw);
      expect(m.problem ?? null, v.name).toBe(v.problem);
      if ("id_error" in v) expect(idProblem(m.id) ?? null, v.name).toBe(v.id_error);
    }
  });

  it("packages", async () => {
    for (const v of vectors.packages) {
      const raw = fromB64(v.package_b64);
      let got: unknown;
      try {
        const p = await verifyPackage(raw);
        got = { ok: true, id: p.manifest.id, version: p.manifest.version, key: p.key, hash: p.hash, sha256: p.sha256, files: p.files.size };
      } catch (e) {
        if (!(e instanceof PackageRefusal)) throw e;
        got = { ok: false, error: e.code };
      }
      expect(got, v.name).toEqual(v.result);
    }
  });

  it("semver parse, order and compare", () => {
    for (const v of vectors.semver.parse) {
      const p = parseSemver(v.input);
      expect(p !== undefined, JSON.stringify(v.input)).toBe(v.ok);
      if (p && v.ok) {
        expect(String(p.major), v.input).toBe(String(v.major));
        expect(String(p.minor), v.input).toBe(String(v.minor));
        expect(String(p.patch), v.input).toBe(String(v.patch));
        expect(p.pre.join("."), v.input).toBe(v.pre);
        expect(p.build.join("."), v.input).toBe(v.build);
      }
    }
    // u64 parts: compared as bigints here (the store's own versions stop at 2^53−1).
    const compare = (a: string, b: string): number => {
      const x = parseSemver(a)!;
      const y = parseSemver(b)!;
      for (const k of ["major", "minor", "patch"] as const) if (x[k] !== y[k]) return x[k] < y[k] ? -1 : 1;
      return comparePre(x.pre, y.pre);
    };
    const order: string[] = vectors.semver.order;
    for (let i = 1; i < order.length; i++) {
      expect(compare(order[i - 1]!, order[i]!), `${order[i - 1]} < ${order[i]}`).toBe(-1);
    }
    for (const v of vectors.semver.compare) {
      expect(compare(v.a, v.b), `${v.a} vs ${v.b}`).toBe(v.cmp);
    }
  });
});
